SELECT CASE WHEN o.discount >= 0.36 THEN 'high' WHEN o.discount >= 0.14 THEN 'mid' ELSE 'low' END AS discount_bucket, SUM(oi.quantity * oi.unit_price) AS revenue FROM order_items oi LEFT OUTER JOIN orders o ON oi.order_id = o.id WHERE oi.order_id IN (20, 30) GROUP BY CASE WHEN o.discount >= 0.36 THEN 'high' WHEN o.discount >= 0.14 THEN 'mid' ELSE 'low' END HAVING SUM(oi.quantity * oi.unit_price) > 42 ORDER BY revenue ASC, discount_bucket DESC LIMIT 20
